import icontract
from typing import List


def is_even(n: int) -> bool:
    return n % 2 == 0


def is_odd(n: int) -> bool:
    return n % 2 != 0


def first_even(lst: List[int]) -> int:
    return next(x for x in lst if is_even(x))


def first_odd(lst: List[int]) -> int:
    return next(x for x in lst if is_odd(x))


@icontract.require(lambda lst: len(lst) > 1)
@icontract.require(lambda lst: any(is_even(x) for x in lst))
@icontract.require(lambda lst: any(is_odd(x) for x in lst))
@icontract.ensure(lambda lst, result: result == first_even(lst) * first_odd(lst))
def findProduct(lst: List[int]) -> int:
    even = None
    odd = None
    for x in lst:
        if even is None and x % 2 == 0:
            even = x
        if odd is None and x % 2 != 0:
            odd = x
    return even * odd
